       after_canvas=legend(leg('background:#f9c738', '해가 머리 위로 올 수 있는 띠', 'Band where the Sun can be overhead'), leg('background:#e6f0ff;border:1px solid #8a94a6', '백야·극야가 생기는 곳', 'Midnight sun and polar night'), leg('background:#2f6fed', '그 밖의 지역', 'Everywhere else'), leg('background:#ff8a3d', '궤도면에 수직인 방향 (점선)', 'Perpendicular to the orbit (dashed)'), leg('background:#7dd3fc', '축 끝이 지나온 길', 'Path of the axis tip')),
